import torch
import triton
import triton.language as tl
from liger_kernel.ops.utils import calculate_settings
from liger_kernel.ops.utils import ensure_contiguous

@triton.jit
def scrc_k1(v0):
    return v0 * tl.sigmoid(v0)

@triton.jit
def scrc_k0(p0, p1, p2, p3, c0: tl.constexpr, c1: tl.constexpr):
    v1 = tl.program_id(0).to(tl.int64)
    p0 += v1 * p3
    p1 += v1 * p3
    p2 += v1 * p3
    v2 = tl.arange(0, c1)
    v3 = v2 < c0
    v4 = tl.load(p0 + v2, mask=v3, other=0).to(tl.float32)
    v5 = tl.load(p1 + v2, mask=v3, other=0)
    v6 = scrc_k1(v4).cast(v5.dtype) * v5
    tl.store(p2 + v2, v6, mask=v3)

@triton.jit
def scrc_k2(v7, p0, p1, p3, c0: tl.constexpr, c1: tl.constexpr):
    v1 = tl.program_id(0).to(tl.int64)
    v7 += v1 * p3
    p0 += v1 * p3
    p1 += v1 * p3
    v2 = tl.arange(0, c1)
    v3 = v2 < c0
    v8 = tl.load(v7 + v2, mask=v3, other=0)
    v4 = tl.load(p0 + v2, mask=v3, other=0).to(tl.float32)
    v5 = tl.load(p1 + v2, mask=v3, other=0)
    v9 = tl.sigmoid(v4)
    v10 = v4 * v9
    v11 = v8 * v10
    v12 = v8 * (v10 * (1 - v9) + v9) * v5
    tl.store(p0 + v2, v12, mask=v3)
    tl.store(p1 + v2, v11, mask=v3)

def scrc_k3(v14, v15):
    v13 = v14.shape
    c0 = v13[-1]
    v14 = v14.view(-1, c0)
    v15 = v15.view(-1, c0)
    v16 = torch.empty_like(v14)
    v17 = v14.shape[0]
    (c1, v18) = calculate_settings(c0)
    scrc_k0[v17,](v14, v15, v16, v16.stride(-2), c0=c0, c1=c1, num_warps=v18)
    return (v14, v15, v16.view(*v13))

def scrc_k4(v14, v15, v19):
    v13 = v19.shape
    c0 = v13[-1]
    v19 = v19.view(-1, c0)
    v17 = v19.shape[0]
    (c1, v18) = calculate_settings(c0)
    scrc_k2[v17,](v19, v14, v15, v19.stride(-2), c0=c0, c1=c1, num_warps=v18)
    return (v14.view(*v13), v15.view(*v13))

class LigerSiLUMulFunction(torch.autograd.Function):

    @staticmethod
    @ensure_contiguous
    def scrc_k5(v25, v14, v15):
        if isinstance(v14, torch.distributed.tensor.DTensor) or isinstance(v15, torch.distributed.tensor.DTensor):
            (v20, v21) = (v14.device_mesh, v14.placements) if isinstance(v14, torch.distributed.tensor.DTensor) else (v15.device_mesh, v15.placements)
            if not isinstance(v14, torch.distributed.tensor.DTensor):
                v14 = torch.distributed.tensor.distribute_tensor(v14, device_mesh=v20, placements=v21)
            if not isinstance(v15, torch.distributed.tensor.DTensor):
                v15 = torch.distributed.tensor.distribute_tensor(v15, device_mesh=v20, placements=v21)
            (v22, v23, v24) = scrc_k3(v14.to_local(), v15.to_local())
            v25.save_for_backward(v22, v23)
            v25.dtensor_metadata = (v20, v21)
            return torch.distributed.tensor.DTensor.from_local(v24, v20, v21)
        else:
            (v14, v15, v16) = scrc_k3(v14, v15)
            v25.save_for_backward(v14, v15)
            v25.dtensor_metadata = None
            return v16

    @staticmethod
    @ensure_contiguous
    def scrc_k6(v25, v19):
        (v14, v15) = v25.saved_tensors
        if v25.dtensor_metadata is not None:
            (v20, v21) = v25.dtensor_metadata
            v26 = v19.to_local() if isinstance(v19, torch.distributed.tensor.DTensor) else torch.distributed.tensor.distribute_tensor(v19, device_mesh=v20, placements=v21)
            (v22, v23) = scrc_k4(v14, v15, v26)
            return (torch.distributed.tensor.DTensor.from_local(v22, v20, v21), torch.distributed.tensor.DTensor.from_local(v23, v20, v21))
        (v14, v15) = scrc_k4(v14, v15, v19)
        return (v14, v15)
